DEBUG - 2026-09-07 15:15:35 --> filterCandidates SQL [source=walkin]: SELECT `c`.`CandidateId`, `c`.`CandidateCode`, `c`.`Fullname`, `c`.`PhoneNo`, `c`.`Email`, `c`.`Source`, `c`.`ProfileMatchPer`, `c`.`ResumePath`, `c`.`ScoreBreakdown`, `c`.`MatchedSkills`, `c`.`ExperienceMatch`, `c`.`VerifiedAt`, `c`.`ExperienceDetails`, `c`.`ExpYrs`, `ja`.`CurrentStage`, `ja`.`CurrentStatus`, `ja`.`AppliedOn`, `ja`.`Jid`, `rs`.`StageOrder` as `CurrentStageOrder`, (SELECT Action FROM CandidateStageTracking
             WHERE ApplicationId = ja.ApplicationId
             ORDER BY ActionAt DESC LIMIT 1) as LastAction
FROM `IHrCandidates` `c`
JOIN `JobApplications` `ja` ON `ja`.`CandidateId` = `c`.`CandidateId`
LEFT JOIN `RecruitmentStages` `rs` ON `rs`.`StageId` = `ja`.`CurrentStage`
WHERE `ja`.`Jid` = '45'
AND c.Source IN ('Walk-in', 'walk-in', 'walk_in', 'walkin', 'upload', 'manual', 'ats')
